mapper.select:
select * from ( select
(IFNULL(day_plan_qty, 0) + IFNULL(night_plan_qty, 0)) as daily_total_qty, b.MONTH_PLAN_QTY as month_plan, CEILING(b.MONTH_REMAIN_QTY) as month_plan_os, TRUNCATE(c.NIGHT_FINISH_QTY, 0) as NIGHT_FINISH_QTY, TRUNCATE(c.DAY_FINISH_QTY, 0) as DAY_FINISH_QTY, d.COLOR_TYPE, d.COLOR_CODE, log.change_machine, log.change_day_plan, log.change_night_plan, ois.original_line_name, ois.original_line_length, CASE WHEN IFNULL(a.cx_class1_plan, 0) + IFNULL(a.cx_class2_plan, 0) + IFNULL(a.cx_class3_plan, 0) + IFNULL(a.cx_class4_plan, 0) + IFNULL(a.cx_class5_plan, 0) > 0 AND a.today_stock + a.total_plan >= 4 * a.day_used THEN 1 ELSE 0 END more_Than_Day_Used_flag from t_xwyy_schedule_result a LEFT JOIN ( select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY from T_XWYY_MONTH_PLAN_SURPLUS where YEAR=#{year,jdbcType=VARCHAR} and MONTH= #{month,jdbcType=VARCHAR} and del_flag = '0' ) b on a.BIG_ROLL_CODE=b.MATERIAL_CODE LEFT JOIN T_XWYY_DAY_FINISH_QTY c ON a.order_no = c.order_no and c.del_flag = '0' LEFT JOIN T_XWYY_BIG_ROLL_COLOR d ON a.BIG_ROLL_CODE = d.BIG_ROLL_CODE AND d.del_Flag = '0' and d.status='0' LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(IF(BEFORE_MACHINE_ID = AFTER_MACHINE_ID,0,1)) change_machine, max(IF(BEFORE_DAY_PLAN = AFTER_DAY_PLAN,0,1)) change_day_plan, max(IF(BEFORE_NIGHT_PLAN = AFTER_NIGHT_PLAN,0,1)) change_night_plan FROM T_XWYY_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 where a.del_flag = '0' and a.schedule_date = #{scheduleDate}
and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and INSTR(ois.original_line_name, #{originalLineName,jdbcType=VARCHAR}) > 0
and a.production_status = #{productionStatus} and instr(concat(',',a.machine_id,','), concat(',',#{machineId},','))>0 and a.IS_RELEASE = #{isRelease} and a.id in #{scheduleId} order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,a.CREATE_TIME ) t
order by ${orderStr}

select count(1)
from t_schedule_publish_record
where procedure_code = #{procedureCode,jdbcType=VARCHAR}
  and schedule_date = #{scheduleDate,jdbcType=DATE}
  and publish_status = '1'
  and del_flag = '0'

select count(1)
from t_xwyy_schedule_result
where del_flag = '0'
and schedule_date = #{scheduleDate}
and big_roll_code = #{bigRollCode}
and machine_id = #{machineId}
and id != #{id}

mapper.insert:
INSERT INTO MES_XWYY_SCHEDULE_RESULT(SCHEDULE_DATE, CD90_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, SAP_MATERIAL_CODE, ORIGINAL_LINE_CODE, MACHINE_CODE, SUPPLY_TIME, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, YES_STOCK, TODAY_STOCK, DAY_USED, DAY_OUT, FAC2_CLASS1_PLAN, FAC2_CLASS2_PLAN, FAC2_CLASS3_PLAN, FAC2_TOTAL_PLAN, FAC5_CLASS1_PLAN, FAC5_CLASS2_PLAN, FAC5_CLASS3_PLAN, FAC5_TOTAL_PLAN, TOTAL_PLAN, ORIGINAL_BRAND, ORIGINAL_BRAND_NUM, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, REMARK, DATA_VERSION, CREATE_DATE, UPDATE_DATE, IS_DELETE, FACTORY_CODE, COMPANY_CODE) SELECT SCHEDULE_DATE, CD90_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, IFNULL(p.SAP_MATERIAL_CODE, bo.SAP_CODE) SAP_MATERIAL_CODE, ORIGINAL_LINE_CODE, m.MACHINE_CODE, SUPPLY_TIME, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, YES_STOCK, TODAY_STOCK, DAY_USED, DAY_OUT, FAC2_CLASS1_PLAN, FAC2_CLASS2_PLAN, FAC2_CLASS3_PLAN, FAC2_TOTAL_PLAN, FAC5_CLASS1_PLAN, FAC5_CLASS2_PLAN, FAC5_CLASS3_PLAN, FAC5_TOTAL_PLAN, TOTAL_PLAN, ORIGINAL_BRAND, ORIGINAL_BRAND_NUM, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, '1' IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, r.REMARK, #{dataVersion} DATA_VERSION, #{createTime} CREATE_DATE, r.UPDATE_TIME UPDATE_DATE, r.DEL_FLAG IS_DELETE, #{factoryCode}, #{companyCode} FROM T_XWYY_SCHEDULE_RESULT r LEFT JOIN T_XWYY_MACHINE_INFO m ON r.machine_id = m.id LEFT JOIN (SELECT max(CORD_SAP) SAP_MATERIAL_CODE, CORD_SPEC FROM T_CONSTRUCTION_VERSION_INFO WHERE DEL_FLAG = '0' GROUP BY CORD_SPEC) p ON r.BIG_ROLL_CODE = p.CORD_SPEC LEFT JOIN (SELECT B.CHILD_CODE, MAX(B.CHILD_MATERIAL_CODE) SAP_CODE FROM T_BOM_INFO B WHERE B.STATUS = '1' AND B.CHILD_MATERIAL_NAME_CODE = 'RUBBER_COVERED' GROUP BY B.CHILD_CODE) BO ON BO.CHILD_CODE = R.BIG_ROLL_CODE WHERE 1=1
AND r.SCHEDULE_DATE = #{scheduleDate} AND r.IS_RELEASE = '0'
AND r.id in #{id}

mapper.select:
select count(1) from t_xwyy_schedule_result
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

mapper.update:
update t_xwyy_schedule_result
set IS_RELEASE = #{isRelease, jdbcType=VARCHAR}
,PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

UPDATE t_schedule_publish_record
   SET PUBLISH_STATUS = #{status}
 WHERE data_version = #{dataVersion}
   AND del_flag = 0

update t_xwyy_schedule_result set IS_RELEASE = #{status}
, PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where id in

    #{id}

update t_xwyy_schedule_result set del_flag = NULL
where id in

    #{id}

mapper.select:
select SUM(DAY_PLAN_QTY + NIGHT_PLAN_QTY)  from t_xwyy_schedule_result
where del_flag = 0
  and SCHEDULE_DATE = #{scheduleDate}
  and ORIGINAL_LINE_CODE = #{originalLineCode}
  and ORIGINAL_BRAND = #{originalBrand}

mapper.update:
update t_xwyy_schedule_result set ORIGINAL_LINE_QTY_NUM = #{originalLineQtyNum}
where del_flag = 0
  and SCHEDULE_DATE = #{scheduleDate}
  and ORIGINAL_LINE_CODE = #{originalLineCode}
  and BIG_ROLL_CODE = #{bigRollCode}

update t_xwyy_schedule_result set ORIGINAL_BRAND_NUM = #{originalBrandNum}
where del_flag = 0
  and SCHEDULE_DATE = #{scheduleDate}
  and ORIGINAL_LINE_CODE = #{originalLineCode}
  and BIG_ROLL_CODE = #{bigRollCode}
and ORIGINAL_BRAND = #{originalBrand}

mapper.select:
SELECT a.ORIGINAL_LINE_CODE, MAX(a.BIG_ROLL_CODE) bigRollCode, IFNULL(ois.original_line_length, 1) original_line_length, SUM(a.DAY_PLAN_QTY + a.NIGHT_PLAN_QTY) sumPlan FROM t_xwyy_schedule_result a LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 WHERE a.del_flag = 0 AND a.SCHEDULE_DATE = #{scheduleDate} AND a.ORIGINAL_LINE_CODE IN
#{originalLineCode}
GROUP BY a.ORIGINAL_LINE_CODE,ois.original_line_length

SELECT a.ORIGINAL_LINE_CODE, a.ORIGINAL_BRAND, MAX(a.BIG_ROLL_CODE) bigRollCode, IFNULL(ois.original_line_length, 1) original_line_length, SUM(a.DAY_PLAN_QTY + a.NIGHT_PLAN_QTY) sumPlan FROM t_xwyy_schedule_result a LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 WHERE a.del_flag = 0 AND a.SCHEDULE_DATE = #{scheduleDate} AND a.ORIGINAL_LINE_CODE IN
#{originalLineCode}
GROUP BY a.ORIGINAL_LINE_CODE, a.ORIGINAL_BRAND, ois.original_line_length

SELECT a.schedule_date, SUM(a.day_plan_qty) as day_plan_qty, SUM(a.night_plan_qty) as night_plan_qty, SUM(a.today_stock) as stock_qty FROM t_xwyy_schedule_result a LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 WHERE a.schedule_date = #{scheduleDate}
and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and INSTR(ois.original_line_name, #{originalLineName,jdbcType=VARCHAR}) > 0
and a.production_status = #{productionStatus}
and instr(concat(',',a.machine_id,','), concat(',',#{machineId},','))>0
and a.IS_RELEASE = #{isRelease}

SELECT SUM(a.night_plan_qty) as night_plan_qty FROM t_xwyy_schedule_result a LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 WHERE a.schedule_date = DATE_SUB(#{scheduleDate}, INTERVAL 1 DAY)
and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and INSTR(ois.original_line_name, #{originalLineName,jdbcType=VARCHAR}) > 0
and a.production_status = #{productionStatus}
and instr(concat(',',a.machine_id,','), concat(',',#{machineId},','))>0
and a.IS_RELEASE = #{isRelease}

SELECT SUM(IFNULL(stock_num,0)) stockQty from t_xwyy_schedule_result a LEFT JOIN t_xwyy_stock s ON a.big_roll_code = s.big_roll_code and s.del_flag = 0 LEFT JOIN t_xwyy_original_line_spec ois ON a.ORIGINAL_LINE_CODE = ois.ORIGINAL_LINE_CODE and ois.del_flag = 0 WHERE stock_date = DATE_SUB(#{scheduleDate}, INTERVAL 1 DAY)
and INSTR(s.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and INSTR(ois.original_line_name, #{originalLineName,jdbcType=VARCHAR}) > 0
and a.production_status = #{productionStatus}
and instr(concat(',',a.machine_id,','), concat(',',#{machineId},','))>0
and a.IS_RELEASE = #{isRelease}

SET @schedule_date = #{scheduleResult.scheduleDate};
-- 纤维压延计划 -- 主查询：通过自关联获取前一天的night_plan_qty SELECT t.BIG_ROLL_CODE as code, MAX(CASE WHEN r.schedule_date = @schedule_date THEN IFNULL(r.cx_class3_plan, 0) + IFNULL(r.cx_class4_plan, 0) END) AS cxPlanQty, -- day1到day5统一采用：当前日day_plan_qty + 前一日night_plan_qty
MAX(CASE WHEN r.schedule_date = DATE_ADD(@schedule_date, INTERVAL ${index} DAY) THEN IFNULL(r.day_plan_qty, 0) + IFNULL(prev_r.night_plan_qty, 0) END) AS day${index}
,t.seq FROM ( -- 基础数据列表 SELECT 'PA11-2' AS BIG_ROLL_CODE, 1 AS seq UNION SELECT 'PA71', 2 -- UNION SELECT '', 3 UNION SELECT 'PA41', 4 UNION SELECT 'NB11', 5 UNION SELECT 'NC11', 6 ) t -- 左连接当前日期的数据（r代表当前日） LEFT JOIN t_xwyy_schedule_result r ON r.BIG_ROLL_CODE = t.BIG_ROLL_CODE AND r.del_flag = '0' AND r.schedule_date BETWEEN @schedule_date AND DATE_ADD(@schedule_date, INTERVAL 15 DAY) -- 自关联前一天的数据（prev_r代表前一日） LEFT JOIN t_xwyy_schedule_result prev_r ON prev_r.BIG_ROLL_CODE = t.BIG_ROLL_CODE AND prev_r.del_flag = '0' -- 前一天的日期 = 当前日的日期 - 1天 AND prev_r.schedule_date = DATE_SUB(r.schedule_date, INTERVAL 1 DAY) GROUP BY t.BIG_ROLL_CODE, t.seq UNION ALL -- 钢带压延计划 SELECT t.BIG_ROLL_CODE, MAX(CASE WHEN r.schedule_date = @schedule_date THEN IFNULL(r.cx_class3_plan, 0) + IFNULL(r.cx_class4_plan, 0) END) AS cxPlanQty, -- day1到day5统一采用：当前日day_plan_qty + 前一日night_plan_qty
MAX(CASE WHEN r.schedule_date = DATE_ADD(@schedule_date, INTERVAL ${index} DAY) THEN IFNULL(r.class1_plan, 0) + IFNULL(prev_r.class2_plan, 0) END) AS day${index}
,t.seq FROM (select 'SD31' BIG_ROLL_CODE, 1 seq union select 'SD32' BIG_ROLL_CODE, 2 seq union select 'SD21' BIG_ROLL_CODE, 3 seq union select 'SD52' BIG_ROLL_CODE, 4 seq union select 'SD41' BIG_ROLL_CODE, 5 seq union select 'SD34' BIG_ROLL_CODE, 6 seq union select 'SD33' BIG_ROLL_CODE, 7 seq) t -- 左连接当前日期的数据（r代表当前日） LEFT JOIN t_gdyy_schedule_result r ON r.BIG_ROLL_CODE = t.BIG_ROLL_CODE AND r.del_flag = '0' AND r.schedule_date BETWEEN @schedule_date AND DATE_ADD(@schedule_date, INTERVAL 15 DAY) -- 自关联前一天的数据（prev_r代表前一日） LEFT JOIN t_gdyy_schedule_result prev_r ON prev_r.BIG_ROLL_CODE = t.BIG_ROLL_CODE AND prev_r.del_flag = '0' -- 前一天的日期 = 当前日的日期 - 1天 AND prev_r.schedule_date = DATE_SUB(r.schedule_date, INTERVAL 1 DAY) GROUP BY t.BIG_ROLL_CODE, t.seq order by seq

mapper.update:
UPDATE t_xwyy_schedule_result a JOIN (
SELECT #{item.code} as code, #{item.standSize} as standSize, #{item.day0} as dayPlanQty, #{item.stockQty} as stockQty FROM DUAL
) b ON a.big_roll_code = b.code SET a.day_plan_qty = b.dayPlanQty, a.day_plan_qty_num = ROUND(b.dayPlanQty / b.standSize, 2), a.today_stock = b.stockQty WHERE a.del_flag = '0' and a.schedule_date = #{scheduleDate}

UPDATE t_gdyy_schedule_result a JOIN (
SELECT #{item.code} as code, #{item.standSize} as standSize, #{item.day0} as dayPlanQty, #{item.stockQty} as stockQty FROM DUAL
) b ON a.big_roll_code = b.code SET a.class1_plan = b.dayPlanQty, a.class1_plan_num = ROUND(b.dayPlanQty / b.standSize, 2), a.stock_qty = b.stockQty WHERE a.del_flag = '0' and a.schedule_date = #{scheduleDate}
